mapper.select:
select m.*, s.nickname as senderNickname, r.nickname as receiverNickname, i.title as itemTitle from item_message m left join `user` s on m.sender_id = s.id left join `user` r on m.receiver_id = r.id left join item i on m.item_id = i.id
where m.sender_id = #{userId} where m.receiver_id = #{userId}
order by m.created_at desc
